import { BrowserWindow, app, Menu } from 'electron';
// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

let mainWindow: BrowserWindow | null = null;

export const createWindow = (): void => {
  // Create the browser window.
  mainWindow = new BrowserWindow({
    height: 1080,
    width: 1920,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      webSecurity: false,
      contextIsolation: true,
      nodeIntegration: true,
    },
  });

  // There is no menu bar, so keep the two shortcuts worth having from the
  // default menu: full screen and the developer tools.
  mainWindow.webContents.on('before-input-event', (event, input) => {
    if (input.type !== 'keyDown') return;
    const win = mainWindow;
    if (!win) return;
    if (input.key === 'F11') {
      win.setFullScreen(!win.isFullScreen());
      event.preventDefault();
    } else if (
      (input.control || input.meta) &&
      input.shift &&
      input.key.toLowerCase() === 'i'
    ) {
      win.webContents.toggleDevTools();
      event.preventDefault();
    }
  });

  // On X11 Chromium draws the full-screen frame before the window manager
  // has resized the window, and the resize then clears the window. Chromium
  // only repaints what changes, so the window stayed black (seen on NoMachine)
  // until a click redrew part of it. The clearing comes 30-100 ms after the
  // event there, and depends on the X server, so repaint all of it a few times.
  const repaintAfterResize = () => {
    for (const delay of [100, 300, 1000]) {
      setTimeout(() => mainWindow?.webContents.invalidate(), delay);
    }
  };
  mainWindow.on('enter-full-screen', repaintAfterResize);
  mainWindow.on('leave-full-screen', repaintAfterResize);

  // and load the index.html of the app.
  mainWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY);
};

app.whenReady().then(() => {
  // No native menu bar: the default Electron menus offered nothing IBEX
  // needs (and Ctrl+R / Ctrl+W silently dropped the canvas), what is useful
  // lives in the header menu.
  Menu.setApplicationMenu(null);

  app.on('activate', () => {
    // On macOS, recreate the window if the app has no windows open
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

// Exit when all windows are closed (except macOS)
app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});
